  'about.we-keep-operations-teams-current-on' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Main headline', 'kind' => 'text', 'en' => 'We keep operations teams current on AI.', 'da' => 'Vi holder driftsteams opdaterede på AI.', 'order' => 15],
  'about.vindex-exists-because-the-way-companies' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Paragraph', 'kind' => 'text', 'en' => 'Vindex exists because the way companies use AI changes every quarter — and scattered articles, slide decks and half-remembered webinars can\'t keep up. We turn that moving target into one calm, structured, always-current knowledge base.', 'da' => 'Vindex findes, fordi måden virksomheder bruger AI på ændrer sig hvert kvartal — og spredte artikler, slides og halvt-huskede webinarer kan ikke følge med. Vi gør det bevægelige mål til én rolig, struktureret og altid opdateret vidensbase.', 'order' => 16],
  'about.our-mission' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Small label above a heading', 'kind' => 'text', 'en' => 'Our mission', 'da' => 'Vores mission', 'order' => 17],
  'about.most-organisations-know-ai-matters-far' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Paragraph', 'kind' => 'text', 'en' => 'Most organisations know AI matters. Far fewer have a single, trusted place that tells their people what to actually do about it — in language their teams understand, updated as the field moves.', 'da' => 'De fleste organisationer ved, at AI betyder noget. Langt færre har ét troværdigt sted, der fortæller deres folk, hvad de rent faktisk skal gøre ved det — i et sprog deres teams forstår, opdateret i takt med feltet.', 'order' => 18],
  'about.vindex-is-that-place-a-sterile' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Paragraph', 'kind' => 'text', 'en' => 'Vindex is that place. A sterile, bank-grade platform where leadership sets the direction and every employee finds exactly the guidance meant for them — nothing more, nothing less.', 'da' => 'Vindex er det sted. En ren platform i bankklasse, hvor ledelsen sætter retningen, og hver medarbejder finder præcis den vejledning, der er tiltænkt dem — hverken mere eller mindre.', 'order' => 19],
  'about.trust-first' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Card / sub heading', 'kind' => 'text', 'en' => 'Trust first', 'da' => 'Tillid først', 'order' => 20],
  'about.security-and-clarity-before-features-the' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Paragraph', 'kind' => 'text', 'en' => 'Security and clarity before features. The platform should feel like a bank, not a startup.', 'da' => 'Sikkerhed og klarhed før funktioner. Platformen skal føles som en bank, ikke en startup.', 'order' => 21],
  'about.always-current' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Card / sub heading', 'kind' => 'text', 'en' => 'Always current', 'da' => 'Altid opdateret', 'order' => 22],
  'about.knowledge-that-s-out-of-date' => ['page' => 'about', 'group' => 'We keep operations teams current on AI.', 'label' => 'Paragraph', 'kind' => 'text', 'en' => 'Knowledge that\'s out of date is worse than none. We keep every module living.', 'da' => 'Viden, der er forældet, er værre end ingen. Vi holder hvert modul levende.', 'order' => 23],
