  'about.built-quietly-delivered-reliably' => ['page' => 'about', 'group' => 'Built quietly, delivered reliably.', 'label' => 'Section heading', 'kind' => 'text', 'en' => 'Built quietly, delivered reliably.', 'da' => 'Bygget i ro, leveret pålideligt.', 'order' => 31],
  'about.we-keep-the-surface-calm-and' => ['page' => 'about', 'group' => 'Built quietly, delivered reliably.', 'label' => 'Paragraph', 'kind' => 'text', 'en' => 'We keep the surface calm and the engineering solid — a dependable backend, a clean admin, and content that\'s genuinely easy to keep up to date. This About text is placeholder for now; send us your real story and we\'ll drop it straight in.', 'da' => 'Vi holder overfladen rolig og teknikken solid — en pålidelig backend, et rent admin-modul og indhold, der er nemt at holde opdateret. Denne Om os-tekst er en pladsholder; send os jeres rigtige historie, så indsætter vi den direkte.', 'order' => 32],
  'about.let-s-build-your-knowledge-base' => ['page' => 'about', 'group' => 'Let\'s build your knowledge base.', 'label' => 'Section heading', 'kind' => 'text', 'en' => 'Let\'s build your knowledge base.', 'da' => 'Lad os bygge jeres vidensbase.', 'order' => 33],
